"use client";

import { useEffect, useId, useLayoutEffect, useRef, useState, type ComponentProps, type KeyboardEvent, type ReactNode } from "react";

import { IconBold, IconCode, IconItalic, IconLink, IconList, IconListOrdered, IconQuote } from "@rhs-ui/icons";
import { applyAction, continueList, type Edit, type MarkdownAction } from "@rhs-ui/primitives/markdown-field/edit";
import { Markdown } from "@rhs-ui/primitives/markdown-field/markdown";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@rhs-ui/primitives/tabs";
import { Textarea } from "@rhs-ui/primitives/textarea";
import { Toolbar, type ToolbarAction } from "@rhs-ui/primitives/toolbar";
import { cn } from "@/lib/utils";

export type { MarkdownAction } from "@rhs-ui/primitives/markdown-field/edit";

export interface MarkdownFieldProps extends Omit<ComponentProps<"textarea">, "value" | "defaultValue" | "onChange" | "rows" | "children"> {
  /** The Markdown, when you control it. It is the plain text that is saved, never HTML. */
  value?: string;
  /** The Markdown to start with, when you do not control it. */
  defaultValue?: string;
  /** Called on every change of the text, whether it is typed, pasted or made by a button. */
  onValueChange?: (value: string) => void;
  /** The buttons in the toolbar, in this order, and the only shortcuts that work: Ctrl or Cmd with B, I and K are bold, italic and link. Default all seven. */
  toolbar?: readonly MarkdownAction[];
  /** How many lines of text the writing area shows before it grows or scrolls. Default 8. */
  rows?: number;
  /** The tab that is open at the start: "write" (the default), or "preview" for text that is read more often than it is edited. */
  defaultTab?: "write" | "preview";
}

const ALL: readonly MarkdownAction[] = ["bold", "italic", "link", "bulleted-list", "numbered-list", "quote", "code"];

// The buttons that belong together sit together, with a divider between the groups.
const GROUP: Record<MarkdownAction, number> = { bold: 0, italic: 0, link: 0, "bulleted-list": 1, "numbered-list": 1, quote: 1, code: 2 };

const BUTTONS: Record<MarkdownAction, { label: string; icon: ReactNode; key?: string }> = {
  bold: { label: "Bold", icon: <IconBold />, key: "B" },
  italic: { label: "Italic", icon: <IconItalic />, key: "I" },
  link: { label: "Link", icon: <IconLink />, key: "K" },
  "bulleted-list": { label: "Bulleted list", icon: <IconList /> },
  "numbered-list": { label: "Numbered list", icon: <IconListOrdered /> },
  quote: { label: "Quote", icon: <IconQuote /> },
  code: { label: "Code", icon: <IconCode /> },
};

const KEYS: Record<string, MarkdownAction> = { b: "bold", i: "italic", k: "link" };

// The tabs and the buttons are a little smaller than their own defaults, so that both fit in one row of a box of ordinary width.
const TAB = "group-data-[variant=pill]/list:h-7 group-data-[variant=pill]/list:px-2.5";

const SYNTAX = ["**bold**", "_italic_", "[link](url)", "- list", "> quote", "`code`"] as const;

/** One piece of syntax in the hint under the box. */
function Syntax({ token }: { token: string }) {
  return <code className="rounded bg-muted px-1.5 py-0.5 font-mono text-[0.6875rem] text-foreground">{token}</code>;
}

/**
 * A writing box for Markdown without an editor library: a textarea with a
 * toolbar (bold, italic, link, bulleted and numbered list, quote, code), and
 * Write and Preview tabs. A button wraps or prefixes the selected text with
 * Markdown syntax, takes it off again when it is already there, and leaves the
 * selection where you can keep typing; Ctrl or Cmd with B, I and K do the same
 * from the keyboard, and Enter in a list starts the next item. Changes go
 * through the browser's own editing, so Undo still works after a button. The
 * preview shows a deliberately small subset as React elements, never as raw
 * HTML, so pasted markup cannot run. The toolbar is one tab stop with arrow
 * keys inside it and comes before the text in the tab order, and a line under
 * the box names the syntax for people who do not know Markdown.
 */
export function MarkdownField({
  value,
  defaultValue = "",
  onValueChange,
  toolbar = ALL,
  rows = 8,
  defaultTab = "write",
  maxLength,
  className,
  disabled,
  onKeyDown,
  ref,
  "aria-describedby": describedBy,
  ...props
}: MarkdownFieldProps) {
  const hintId = useId();
  const [own, setOwn] = useState(defaultValue);
  const [tab, setTab] = useState<"write" | "preview">(defaultTab);
  const [command, setCommand] = useState("Ctrl+");
  const [said, setSaid] = useState("");
  const area = useRef<HTMLTextAreaElement | null>(null);
  // Where the selection should be once the text has been written, when the browser's own editing could not be used.
  const pending = useRef<[number, number] | null>(null);
  const text = value ?? own;
  const shown = new Set(toolbar);
  const height = `calc(${rows} * 1.625 * 0.875rem + 1rem)`;

  // The shortcut is written the way the platform writes it. The server cannot know it, so Ctrl is what is rendered first.
  useEffect(() => {
    setCommand(/mac|iphone|ipad/i.test(navigator.platform || navigator.userAgent) ? "⌘" : "Ctrl+");
  }, []);

  useEffect(() => {
    if (!said) return;
    const timer = window.setTimeout(() => setSaid(""), 4000);
    return () => window.clearTimeout(timer);
  }, [said]);

  useLayoutEffect(() => {
    const selection = pending.current;
    if (!selection) return;
    pending.current = null;
    area.current?.setSelectionRange(selection[0], selection[1]);
  });

  function write(next: string) {
    if (value === undefined) setOwn(next);
    onValueChange?.(next);
  }

  function apply(edit: Edit) {
    const node = area.current;
    if (!node) return;
    const next = text.slice(0, edit.from) + edit.text + text.slice(edit.to);
    if (maxLength !== undefined && next.length > maxLength && next.length > text.length) {
      setSaid(`There is no room for that: the limit is ${maxLength} characters.`);
      node.focus();
      return;
    }
    node.focus();
    node.setSelectionRange(edit.from, edit.to);
    // insertText and delete are edits the browser knows about, so Ctrl or Cmd+Z undoes a button the way it undoes typing.
    let done = false;
    try {
      done = edit.text === "" ? document.execCommand("delete") : document.execCommand("insertText", false, edit.text);
    } catch {
      done = false;
    }
    if (done) {
      node.setSelectionRange(edit.start, edit.end);
    } else {
      pending.current = [edit.start, edit.end];
      write(next);
    }
  }

  function run(action: MarkdownAction) {
    const node = area.current;
    if (!node) return;
    apply(applyAction(action, { value: text, start: node.selectionStart, end: node.selectionEnd }));
  }

  function keyDown(event: KeyboardEvent<HTMLTextAreaElement>) {
    onKeyDown?.(event);
    if (event.defaultPrevented || event.nativeEvent.isComposing) return;
    if ((event.metaKey || event.ctrlKey) && !event.altKey && !event.shiftKey) {
      const action = KEYS[event.key.toLowerCase()];
      if (action && shown.has(action)) {
        event.preventDefault();
        run(action);
      }
    } else if (event.key === "Enter" && !event.shiftKey && !event.metaKey && !event.ctrlKey && !event.altKey) {
      const node = event.currentTarget;
      const edit = continueList({ value: text, start: node.selectionStart, end: node.selectionEnd });
      if (edit) {
        event.preventDefault();
        apply(edit);
      }
    }
  }

  const groups: ToolbarAction[][] = [];
  let last = -1;
  for (const action of toolbar) {
    const button = BUTTONS[action];
    if (GROUP[action] !== last) groups.push([]);
    last = GROUP[action];
    groups[groups.length - 1]?.push({
      id: action,
      label: button.key ? `${button.label} (${command}${button.key})` : button.label,
      icon: button.icon,
      disabled,
      onSelect: () => run(action),
    });
  }

  const near = maxLength !== undefined && maxLength - text.length <= Math.max(10, Math.round(maxLength * 0.1));

  return (
    <div data-slot="markdown-field" className={cn("w-full", className)}>
      <Tabs
        value={tab}
        onValueChange={(next) => setTab(next === "preview" ? "preview" : "write")}
        className="gap-0 overflow-hidden rounded-md border border-input bg-background shadow-xs transition-[border-color,box-shadow] duration-150 motion-reduce:transition-none has-[textarea:focus-visible]:border-ring has-[textarea:focus-visible]:ring-[3px] has-[textarea:focus-visible]:ring-ring/40"
      >
        <div className="flex flex-wrap items-center justify-between gap-x-3 gap-y-1.5 border-b border-border bg-muted/40 px-2 py-1.5">
          <TabsList variant="pill" aria-label="Writing mode" className="h-8 bg-muted/80">
            <TabsTrigger value="write" className={TAB}>
              Write
            </TabsTrigger>
            <TabsTrigger value="preview" className={TAB}>
              Preview
            </TabsTrigger>
          </TabsList>
          {tab === "write" && groups.length > 0 ? (
            <Toolbar label="Formatting" groups={groups} className="gap-0.5 rounded-none border-0 bg-transparent p-0 [&_button]:size-7" />
          ) : null}
        </div>
        {/* The text stays mounted behind the preview: it keeps its undo history, and a form still posts it. The panel itself is no tab stop: the text in it is. */}
        <TabsContent value="write" forceMount tabIndex={-1} className="data-[state=inactive]:hidden">
          <Textarea
            ref={(node) => {
              area.current = node;
              if (typeof ref === "function") ref(node);
              else if (ref) ref.current = node;
            }}
            rows={rows}
            maxLength={maxLength}
            disabled={disabled}
            aria-describedby={[describedBy, hintId].filter(Boolean).join(" ")}
            {...props}
            value={text}
            onChange={(event) => write(event.target.value)}
            onKeyDown={keyDown}
            style={{ minHeight: height }}
            className="max-h-[28rem] min-h-0 resize-y rounded-none border-0 bg-transparent px-3 py-2 shadow-none focus-visible:border-0 focus-visible:ring-0"
          />
        </TabsContent>
        <TabsContent value="preview" className="px-3 py-2" style={{ minHeight: height }}>
          {text.trim() ? <Markdown text={text} /> : <p className="text-sm text-muted-foreground">Nothing to preview yet.</p>}
        </TabsContent>
        <div className="grid grid-cols-[minmax(0,1fr)_auto] items-start gap-x-4 border-t border-border bg-muted/40 px-3 py-2 text-xs text-muted-foreground">
          <p id={hintId} className="flex flex-wrap items-center gap-x-2 gap-y-1">
            <span>Markdown:</span>
            {SYNTAX.slice(0, -2).map((token) => (
              <Syntax key={token} token={token} />
            ))}
            {/* The last two stay together, so on a narrow screen the hint never ends with one chip on a line of its own. */}
            <span className="flex items-center gap-x-2">
              {SYNTAX.slice(-2).map((token) => (
                <Syntax key={token} token={token} />
              ))}
            </span>
          </p>
          {maxLength !== undefined ? (
            <span aria-live={near ? "polite" : "off"} className={cn("py-0.5 tabular-nums", near && "text-foreground")}>
              {text.length}/{maxLength}
            </span>
          ) : null}
        </div>
      </Tabs>
      <span role="status" className="sr-only">
        {said}
      </span>
    </div>
  );
}

export type MarkdownAction = "bold" | "italic" | "link" | "bulleted-list" | "numbered-list" | "quote" | "code";

/** A text and what is selected in it, as positions between characters. A caret is a selection with the same start and end. */
export interface Selection {
  value: string;
  start: number;
  end: number;
}

/** A change to make: the characters from `from` to `to` become `text`, and afterwards `start` to `end` is selected (positions in the changed text). */
export interface Edit {
  from: number;
  to: number;
  text: string;
  start: number;
  end: number;
}

const WORD_CHAR = /[\p{L}\p{N}_]/u;

/** A caret inside or at the end of a word stands for the word, so Bold on a caret makes the word bold. */
function expandToWord(selection: Selection): Selection {
  if (selection.start !== selection.end) return selection;
  let start = selection.start;
  let end = selection.end;
  while (start > 0 && WORD_CHAR.test(selection.value.charAt(start - 1))) start -= 1;
  while (end < selection.value.length && WORD_CHAR.test(selection.value.charAt(end))) end += 1;
  return { ...selection, start, end };
}

/**
 * Wraps the selection in a pair of markers, or takes them off when they are
 * already there, just outside the selection or in it. Spaces at the edges of
 * the selection stay outside the markers, because `** bold**` is not bold. With
 * nothing selected the markers go around a placeholder that is selected, so
 * typing replaces it.
 */
function wrap(selection: Selection, open: string, close: string, placeholder: string): Edit {
  const { value, start, end } = expandToWord(selection);
  const selected = value.slice(start, end);
  if (start >= open.length && value.slice(start - open.length, start) === open && value.slice(end, end + close.length) === close) {
    const from = start - open.length;
    return { from, to: end + close.length, text: selected, start: from, end: from + selected.length };
  }
  if (selected.length >= open.length + close.length && selected.startsWith(open) && selected.endsWith(close)) {
    const inner = selected.slice(open.length, selected.length - close.length);
    return { from: start, to: end, text: inner, start, end: start + inner.length };
  }
  const core = selected.trim();
  if (!core) {
    return { from: start, to: end, text: open + placeholder + close, start: start + open.length, end: start + open.length + placeholder.length };
  }
  const lead = selected.length - selected.trimStart().length;
  const trail = selected.length - selected.trimEnd().length;
  const text = selected.slice(0, lead) + open + core + close + selected.slice(selected.length - trail);
  const from = start + lead + open.length;
  return { from: start, to: end, text, start: from, end: from + core.length };
}

/** Several lines of code become a fenced block, on lines of their own; a fenced block that is selected whole loses its fences. */
function fence(selection: Selection): Edit {
  const { value, start, end } = selection;
  const selected = value.slice(start, end);
  const fenced = /^```[\w-]*\n([\s\S]*?)\n?```$/.exec(selected.trim());
  if (fenced) {
    const inner = fenced[1] ?? "";
    return { from: start, to: end, text: inner, start, end: start + inner.length };
  }
  const before = start > 0 && value.charAt(start - 1) !== "\n" ? "\n" : "";
  const after = end < value.length && value.charAt(end) !== "\n" ? "\n" : "";
  const inside = start + before.length + 4;
  return { from: start, to: end, text: `${before}\`\`\`\n${selected}\n\`\`\`${after}`, start: inside, end: inside + selected.length };
}

function code(selection: Selection): Edit {
  return selection.value.slice(selection.start, selection.end).includes("\n") ? fence(selection) : wrap(selection, "`", "`", "code");
}

/** [text](https://): the selected text becomes the label, a copied address becomes the target, and the part still to be written is selected. */
function link(selection: Selection): Edit {
  const { value, start, end } = selection;
  const selected = value.slice(start, end).trim();
  if (/^https?:\/\/\S+$/i.test(selected)) {
    return { from: start, to: end, text: `[link text](${selected})`, start: start + 1, end: start + 1 + "link text".length };
  }
  if (selected) {
    const at = start + selected.length + 3;
    return { from: start, to: end, text: `[${selected}](https://)`, start: at, end: at + "https://".length };
  }
  return { from: start, to: end, text: "[link text](https://)", start: start + 1, end: start + 1 + "link text".length };
}

const BULLET = /^(\s*)[-*+]\s+/;
const NUMBER = /^(\s*)\d+[.)]\s+/;
const QUOTE = /^(\s*)>\s?/;
const LIST_MARKER = /^(\s*)(?:[-*+]|\d+[.)])\s+/;

/**
 * Puts a marker in front of every line the selection touches, or takes it off
 * when every line has it already. A list marker replaces the other kind (a
 * bulleted line becomes numbered), blank lines are left alone, and numbers
 * count the lines that have one. A caret on an empty line starts the list.
 */
function prefixLines(selection: Selection, kind: "bullet" | "number" | "quote"): Edit {
  const { value, start, end } = selection;
  const from = value.lastIndexOf("\n", start - 1) + 1;
  // A selection that ends right after a line break (a triple click) does not include the line after it.
  const to = end > start && value.charAt(end - 1) === "\n" ? end - 1 : end;
  const found = value.indexOf("\n", to);
  const stop = found === -1 ? value.length : found;
  const block = value.slice(from, stop);
  const lines = block.split("\n");
  const own = kind === "bullet" ? BULLET : kind === "number" ? NUMBER : QUOTE;
  const filled = lines.filter((line) => line.trim() !== "");
  const allMarked = filled.length > 0 && filled.every((line) => own.test(line));
  let counted = 0;
  const changed = lines.map((line) => {
    if (line.trim() !== "" && allMarked) return line.replace(own, "$1");
    if (line.trim() === "" && lines.length > 1) return line;
    counted += 1;
    if (kind === "quote") return QUOTE.test(line) ? line : `${/^\s*/.exec(line)?.[0] ?? ""}> ${line.trimStart()}`;
    const indent = /^\s*/.exec(line)?.[0] ?? "";
    const marker = kind === "bullet" ? "- " : `${counted}. `;
    return indent + marker + line.replace(LIST_MARKER, "$1").trimStart();
  });
  const text = changed.join("\n");
  if (start === end && lines.length === 1) {
    const caret = Math.max(from, start + (text.length - block.length));
    return { from, to: stop, text, start: caret, end: caret };
  }
  return { from, to: stop, text, start: from, end: from + text.length };
}

/** What the toolbar button or shortcut for `action` does to the text. */
export function applyAction(action: MarkdownAction, selection: Selection): Edit {
  switch (action) {
    case "bold":
      return wrap(selection, "**", "**", "bold text");
    case "italic":
      return wrap(selection, "_", "_", "italic text");
    case "code":
      return code(selection);
    case "link":
      return link(selection);
    case "bulleted-list":
      return prefixLines(selection, "bullet");
    case "numbered-list":
      return prefixLines(selection, "number");
    case "quote":
      return prefixLines(selection, "quote");
  }
}


const ITEM = /^(\s*)(?:([-*+])|(\d+)([.)]))(\s+)(.*)$/;

/**
 * What Enter does on a line of a list: another item, numbered on from this one,
 * with whatever follows the caret moving down into it; or, on an item with
 * nothing in it, the end of the list. Null when the caret is not behind a
 * marker, so the line break is the browser's.
 */
export function continueList(selection: Selection): Edit | null {
  if (selection.start !== selection.end) return null;
  const { value, start } = selection;
  const lineStart = value.lastIndexOf("\n", start - 1) + 1;
  const found = value.indexOf("\n", start);
  const lineEnd = found === -1 ? value.length : found;
  const match = ITEM.exec(value.slice(lineStart, lineEnd));
  if (!match) return null;
  const [, indent = "", bullet, number, delimiter = "", gap = " ", rest = ""] = match;
  const marker = bullet ?? `${number ?? ""}${delimiter}`;
  if (start - lineStart < indent.length + marker.length + gap.length) return null;
  if (rest.trim() === "") return { from: lineStart, to: lineEnd, text: "", start: lineStart, end: lineStart };
  const next = bullet ?? `${Number(number) + 1}${delimiter}`;
  const text = `\n${indent}${next} `;
  return { from: start, to: start, text, start: start + text.length, end: start + text.length };
}

import { createElement, type ComponentProps, type ReactNode } from "react";

import { cn } from "@/lib/utils";

export interface MarkdownProps extends Omit<ComponentProps<"div">, "children"> {
  /** The Markdown to show: headings, emphasis, links, lists (one level deep), quotes, inline code and fenced code. Anything else is plain text. */
  text: string;
  /** The heading level a single # becomes, 1 to 5. Default 2, so a page that shows user text keeps its own h1; ## is one level below, down to h6. */
  headingLevel?: 1 | 2 | 3 | 4 | 5;
}

type Block =
  | { type: "heading"; level: number; text: string }
  | { type: "paragraph"; text: string }
  | { type: "quote"; blocks: Block[] }
  | { type: "list"; ordered: boolean; start: number; items: string[] }
  | { type: "code"; text: string };

const FENCE = /^ {0,3}(`{3,}|~{3,})\s*[\w+-]*\s*$/;
const HEADING = /^ {0,3}(#{1,6})[ \t]+(.*?)(?:[ \t]+#+)?[ \t]*$/;
const QUOTE_LINE = /^ {0,3}>/;
const BULLET_LINE = /^\s*[-*+][ \t]+(.*)$/;
const NUMBER_LINE = /^\s*(\d{1,9})[.)][ \t]+(.*)$/;

const startsBlock = (line: string) => FENCE.test(line) || HEADING.test(line) || QUOTE_LINE.test(line) || BULLET_LINE.test(line) || NUMBER_LINE.test(line);

/** The blocks of a text: what is on a line of its own (a heading, an item of a list, a quote, a fence) and what runs on from line to line (a paragraph). */
function parseBlocks(source: string): Block[] {
  const lines = source.replace(/\r\n?/g, "\n").split("\n");
  const blocks: Block[] = [];
  let index = 0;
  while (index < lines.length) {
    const line = lines[index] ?? "";
    if (line.trim() === "") {
      index += 1;
      continue;
    }
    const fence = FENCE.exec(line);
    if (fence) {
      const mark = fence[1] ?? "```";
      const body: string[] = [];
      index += 1;
      // The fence closes with at least as many of the same character, or at the end of the text.
      while (index < lines.length && !new RegExp(`^ {0,3}${mark.charAt(0) === "`" ? "`" : "~"}{${mark.length},}\\s*$`).test(lines[index] ?? "")) {
        body.push(lines[index] ?? "");
        index += 1;
      }
      index += 1;
      blocks.push({ type: "code", text: body.join("\n") });
      continue;
    }
    const heading = HEADING.exec(line);
    if (heading) {
      blocks.push({ type: "heading", level: (heading[1] ?? "#").length, text: heading[2] ?? "" });
      index += 1;
      continue;
    }
    if (QUOTE_LINE.test(line)) {
      const inner: string[] = [];
      while (index < lines.length && QUOTE_LINE.test(lines[index] ?? "")) {
        inner.push((lines[index] ?? "").replace(/^ {0,3}>[ \t]?/, ""));
        index += 1;
      }
      blocks.push({ type: "quote", blocks: parseBlocks(inner.join("\n")) });
      continue;
    }
    const bullet = BULLET_LINE.exec(line);
    const number = NUMBER_LINE.exec(line);
    if (bullet || number) {
      const ordered = Boolean(number);
      const start = number ? Number(number[1]) : 1;
      const items: string[] = [];
      while (index < lines.length) {
        const current = lines[index] ?? "";
        const item = ordered ? NUMBER_LINE.exec(current) : BULLET_LINE.exec(current);
        if (!item) {
          // A line that is indented and not a marker goes on with the item before it.
          if (items.length > 0 && /^\s+\S/.test(current) && !startsBlock(current)) {
            items[items.length - 1] += `\n${current.trim()}`;
            index += 1;
            continue;
          }
          break;
        }
        items.push((ordered ? item[2] : item[1]) ?? "");
        index += 1;
      }
      blocks.push({ type: "list", ordered, start, items });
      continue;
    }
    const paragraph: string[] = [];
    while (index < lines.length && (lines[index] ?? "").trim() !== "" && (paragraph.length === 0 || !startsBlock(lines[index] ?? ""))) {
      paragraph.push(lines[index] ?? "");
      index += 1;
    }
    blocks.push({ type: "paragraph", text: paragraph.map((row) => row.trim()).join("\n") });
  }
  return blocks;
}

const ESCAPABLE = "\\`*_{}[]()#+-.!|~<>";

/** A link target that is safe to put in an href: no script, no data. Web addresses, mail, phone numbers, anchors and paths are fine. */
function safeHref(raw: string): string | null {
  const url = raw.trim();
  if (!url) return null;
  // Control characters and spaces are dropped before the scheme is read, as a browser does, so "java script:" cannot hide.
  const compact = Array.from(url)
    .filter((char) => char.charCodeAt(0) > 32 && !(char.charCodeAt(0) >= 127 && char.charCodeAt(0) <= 159))
    .join("");
  const scheme = /^([a-z][a-z0-9+.-]*):/i.exec(compact)?.[1]?.toLowerCase();
  if (scheme) return ["http", "https", "mailto", "tel"].includes(scheme) ? url : null;
  return url;
}

/** Where `[label](address)` starts at `from`: the label, the address and where it ends, or null when it is not a link. */
function readLink(text: string, from: number): { label: string; href: string; end: number } | null {
  let depth = 0;
  let close = -1;
  for (let at = from; at < text.length; at += 1) {
    const char = text.charAt(at);
    if (char === "\\") at += 1;
    else if (char === "[") depth += 1;
    else if (char === "]") {
      depth -= 1;
      if (depth === 0) {
        close = at;
        break;
      }
    }
  }
  if (close === -1 || text.charAt(close + 1) !== "(") return null;
  let parens = 1;
  let end = -1;
  for (let at = close + 2; at < text.length; at += 1) {
    const char = text.charAt(at);
    if (char === "\\") at += 1;
    else if (char === "(") parens += 1;
    else if (char === ")") {
      parens -= 1;
      if (parens === 0) {
        end = at;
        break;
      }
    }
  }
  if (end === -1) return null;
  // An address, optionally in <angle brackets>, and then perhaps a title in quotes, which is not shown. Anything else in the brackets means this is not a link.
  const inside = /^(<[^>]*>|\S+)(?:\s+(?:"[^"]*"|'[^']*'|\([^)]*\)))?$/.exec(text.slice(close + 2, end).trim());
  if (!inside) return null;
  return { label: text.slice(from + 1, close), href: (inside[1] ?? "").replace(/^<(.*)>$/, "$1"), end: end + 1 };
}

/** The index of the marker that closes a span opened with `size` of `mark`, or -1. Code spans and escapes are stepped over, and so are runs of another length. */
function findClose(text: string, from: number, mark: string, size: number): number {
  for (let at = from; at < text.length; at += 1) {
    const char = text.charAt(at);
    if (char === "\\") {
      at += 1;
    } else if (char === "`") {
      let run = 1;
      while (text.charAt(at + run) === "`") run += 1;
      const closing = text.indexOf("`".repeat(run), at + run);
      if (closing !== -1) at = closing + run - 1;
      else at += run - 1;
    } else if (char === mark) {
      let run = 1;
      while (text.charAt(at + run) === mark) run += 1;
      const before = text.charAt(at - 1);
      const after = text.charAt(at + run);
      const flanks = at > from && !/\s/.test(before);
      // An underscore inside a word is just a character: snake_case stays as it is.
      const inWord = mark === "_" && /[\p{L}\p{N}]/u.test(after);
      if (run === size && flanks && !inWord) return at;
      at += run - 1;
    }
  }
  return -1;
}

function renderInline(text: string, keyPrefix: string, inLink = false): ReactNode[] {
  const nodes: ReactNode[] = [];
  let buffer = "";
  let counter = 0;
  const key = () => `${keyPrefix}-${(counter += 1)}`;
  const flush = () => {
    if (buffer) nodes.push(buffer);
    buffer = "";
  };
  let at = 0;
  while (at < text.length) {
    const char = text.charAt(at);
    if (char === "\\" && at + 1 < text.length && ESCAPABLE.includes(text.charAt(at + 1))) {
      buffer += text.charAt(at + 1);
      at += 2;
      continue;
    }
    if (char === "\n") {
      flush();
      nodes.push(<br key={key()} />);
      at += 1;
      continue;
    }
    if (char === "`") {
      let run = 1;
      while (text.charAt(at + run) === "`") run += 1;
      const fence = "`".repeat(run);
      let closing = text.indexOf(fence, at + run);
      // The closing run must be as long as the opening one, not part of a longer one.
      while (closing !== -1 && text.charAt(closing + run) === "`") {
        let longer = run;
        while (text.charAt(closing + longer) === "`") longer += 1;
        closing = text.indexOf(fence, closing + longer);
      }
      if (closing !== -1) {
        flush();
        const inner = text.slice(at + run, closing);
        nodes.push(
          <code key={key()} className="rounded-[0.3rem] bg-muted px-1.5 py-0.5 font-mono text-[0.8125em] text-foreground">
            {inner.length > 2 && inner.startsWith(" ") && inner.endsWith(" ") ? inner.slice(1, -1) : inner}
          </code>,
        );
        at = closing + run;
        continue;
      }
      buffer += fence;
      at += run;
      continue;
    }
    if (char === "[" && !inLink) {
      const link = readLink(text, at);
      const href = link ? safeHref(link.href) : null;
      if (link && href) {
        flush();
        const external = /^(https?:)?\/\//i.test(href);
        nodes.push(
          <a
            key={key()}
            href={href}
            target={external ? "_blank" : undefined}
            rel={external ? "noopener noreferrer" : undefined}
            className="font-medium text-foreground underline decoration-foreground/30 underline-offset-4 transition-colors duration-150 motion-reduce:transition-none hover:decoration-foreground"
          >
            {renderInline(link.label, `${keyPrefix}-${counter}`, true)}
          </a>,
        );
        at = link.end;
        continue;
      }
    }
    if (char === "*" || char === "_") {
      let run = 1;
      while (text.charAt(at + run) === char) run += 1;
      const before = text.charAt(at - 1);
      const after = text.charAt(at + run);
      // An opening marker is followed by text, and an underscore is not an opening marker in the middle of a word.
      const opens = after !== "" && !/\s/.test(after) && !(char === "_" && /[\p{L}\p{N}]/u.test(before));
      if (opens && run <= 3) {
        let used = 0;
        let closeAt = -1;
        for (const size of run === 3 ? [3, 2, 1] : run === 2 ? [2, 1] : [1]) {
          closeAt = findClose(text, at + size, char, size);
          if (closeAt > at + size) {
            used = size;
            break;
          }
          closeAt = -1;
        }
        if (used > 0) {
          flush();
          const inner = renderInline(text.slice(at + used, closeAt), `${keyPrefix}-${counter + 1}`, inLink);
          const id = key();
          nodes.push(
            used === 3 ? (
              <strong key={id} className="font-semibold">
                <em>{inner}</em>
              </strong>
            ) : used === 2 ? (
              <strong key={id} className="font-semibold">
                {inner}
              </strong>
            ) : (
              <em key={id}>{inner}</em>
            ),
          );
          at = closeAt + used;
          continue;
        }
      }
      buffer += text.slice(at, at + run);
      at += run;
      continue;
    }
    buffer += char;
    at += 1;
  }
  flush();
  return nodes;
}

const HEADING_CLASS = ["text-xl", "text-lg", "text-base", "text-[0.9375rem]", "text-sm", "text-sm"] as const;

function renderBlocks(blocks: readonly Block[], keyPrefix: string, headingLevel: number): ReactNode[] {
  return blocks.map((block, index) => {
    const key = `${keyPrefix}-${index}`;
    switch (block.type) {
      case "heading": {
        const level = Math.min(6, headingLevel + block.level - 1);
        return createElement(`h${level}`, { key, className: cn("font-semibold tracking-[-0.015em] text-foreground", HEADING_CLASS[level - 1]) }, renderInline(block.text, key));
      }
      case "paragraph":
        return <p key={key}>{renderInline(block.text, key)}</p>;
      case "quote":
        return (
          <blockquote key={key} className="grid gap-2 border-l-2 border-border pl-3 text-muted-foreground">
            {renderBlocks(block.blocks, key, headingLevel)}
          </blockquote>
        );
      case "list": {
        const items = block.items.map((item, position) => <li key={`${key}-${position}`}>{renderInline(item, `${key}-${position}`)}</li>);
        return block.ordered ? (
          <ol key={key} start={block.start} className="list-decimal space-y-1 pl-5 marker:text-muted-foreground marker:tabular-nums">
            {items}
          </ol>
        ) : (
          <ul key={key} className="list-disc space-y-1 pl-5 marker:text-muted-foreground">
            {items}
          </ul>
        );
      }
      case "code":
        return (
          <pre
            key={key}
            // A block that scrolls sideways must be reachable by keyboard too.
            tabIndex={0}
            className="relative overflow-x-auto rounded-lg border border-border bg-muted/50 p-3 font-mono text-[0.8125rem] leading-relaxed text-foreground outline-none focus-visible:ring-[3px] focus-visible:ring-ring/40"
          >
            <code>{block.text}</code>
          </pre>
        );
    }
  });
}

/**
 * The small subset of Markdown that a writing box needs, shown as React
 * elements: headings, bold and italic, links, bulleted and numbered lists,
 * quotes, inline code and fenced code, with a single line break kept as a line
 * break. It never produces raw HTML, so markup in the text is just text, and a
 * link whose address is script or data is not made a link at all: what was
 * written stays on the page as plain text. Lists are one level deep, so an
 * indented item is shown flat, at the level of the others. Headings start at h2
 * by default, so a page that shows user text keeps one h1 of its own. Use it
 * for the Preview of the Markdown field, and anywhere the saved text is shown
 * again, so it looks the same in both places.
 */
export function Markdown({ text, headingLevel = 2, className, ...props }: MarkdownProps) {
  return (
    <div data-slot="markdown" className={cn("grid gap-3 text-sm leading-relaxed break-words text-foreground", className)} {...props}>
      {renderBlocks(parseBlocks(text), "md", headingLevel)}
    </div>
  );
}
